#include<bits/stdc++.h>
using namespace std;int main(int ac,char**av){ifstream f(av[1]);int T,n; f>>T>>n;if(!f||T!=96)return 2;int mins[12];fill(mins,mins+12,100);for(int t=0;t<T;t++){int l;f>>l;vector<int>C(l);for(int&x:C)f>>x;for(int s=0;s<2048;s++){int r=__builtin_popcount(2047^s);if(r!=2&&r!=3&&r!=5&&r!=6)continue;for(int u=s;;u=(u-1)&s){int B=0;for(int x:C)B+=__builtin_popcount((x^u)&s)<4;if(B<mins[r]){mins[r]=B;printf("FREE r=%d min blockers=%d code=%d permkeep=%d y=%d\n",r,B,t,s,u);fflush(stdout);}if(!u)break;}}}for(int r:{2,3,5,6})cout<<"r "<<r<<" best "<<mins[r]<<endl;}